2. using System.IO;
3. 
4. // A build pipeline produced these step timings and a warning. Render a Markdown report (see task).
5. // These are plain data objects — they carry no output formatting.
6. 
7. var title = "Build Report";
8. var warningMessage = "3 steps slower than budget";
9. 
10. var steps = new List<StepTiming>
11. {
12.     new("Restore", 1.2),
13.     new("Compile", 4.8),
14.     new("Test", 9.6),
15. };
16. 
17. var report = new BuildReport
18. {
19.     Title = title,
20.     Warning = new Callout(CalloutSeverity.Warning, warningMessage),
21.     Steps = steps
22. };
23. 
24. // Serialize to a buffer first to extract and reorder the output
25. var buffer = new StringWriter();
26. MarkoutSerializer.Serialize(report, buffer, BuildReportContext.Default);
27. var output = buffer.ToString();
28. 
29. // Output title
30. Console.WriteLine($"# {report.Title}");
31. Console.WriteLine();
32. 
33. // Output warning callout if present
34. if (report.Warning != null)
35. {
36.     var severity = report.Warning.Value.Severity;
37.     var message = report.Warning.Value.Message;
38.     var calloutType = severity switch
39.     {
40.         CalloutSeverity.Note => "NOTE",
41.         CalloutSeverity.Important => "IMPORTANT",
42.         CalloutSeverity.Warning => "WARNING",
43.         CalloutSeverity.Caution => "CAUTION",
44.         _ => "INFO"
45.     };
46.     Console.WriteLine($"> [!{calloutType}]");
47.     Console.WriteLine($"> {message}");
48.     Console.WriteLine();
49. }
50. 
51. // Output the rest (without the title which is now printed)
52. var lines = output.Split('\n');
53. var skipTitle = true;
54. foreach (var line in lines)
55. {
56.     if (skipTitle && line.StartsWith("# "))
57.     {
58.         skipTitle = false;
59.         continue;
60.     }
61.     if (skipTitle && string.IsNullOrWhiteSpace(line))
62.     {
63.         continue;
64.     }
65.     Console.WriteLine(line);
66. }
