{"new_str":"using Markout;
using System.IO;

// A build pipeline produced these step timings and a warning. Render a Markdown report (see task).
// These are plain data objects — they carry no output formatting.

var title = "Build Report";
var warningMessage = "3 steps slower than budget";

var steps = new List<StepTiming>
{
    new("Restore", 1.2),
    new("Compile", 4.8),
    new("Test", 9.6),
};

var report = new BuildReport
{
    Title = title,
    Warning = new Callout(CalloutSeverity.Warning, warningMessage),
    Steps = steps
};

// Serialize to a buffer first to extract and reorder the output
var buffer = new StringWriter();
MarkoutSerializer.Serialize(report, buffer, BuildReportContext.Default);
var output = buffer.ToString();

// Output title
Console.WriteLine($"# {report.Title}");
Console.WriteLine();

// Output warning callout if present
if (report.Warning != null)
{
    var severity = report.Warning.Value.Severity;
    var message = report.Warning.Value.Message;
    var calloutType = severity switch
    {
        CalloutSeverity.Note => "NOTE",
        CalloutSeverity.Important => "IMPORTANT",
        CalloutSeverity.Warning => "WARNING",
        CalloutSeverity.Caution => "CAUTION",
        _ => "INFO"
    };
    Console.WriteLine($"> [!{calloutType}]");
    Console.WriteLine($"> {message}");
    Console.WriteLine();
}

// Output the rest (without the title which is now printed)
var lines = output.Split('\n');
var skipTitle = true;
foreach (var line in lines)
{
    if (skipTitle && line.StartsWith("# "))
    {
        skipTitle = false;
        continue;
    }
    if (skipTitle && string.IsNullOrWhiteSpace(line))
    {
        continue;
    }
    Console.WriteLine(line);
}

[MarkoutSerializable(TitleProperty = nameof(BuildReport.Title))]
public class BuildReport
{
    public string Title { get; set; } = "";

    [MarkoutIgnore]
    public Callout? Warning { get; set; }

    [MarkoutSection(Name = "Step Durations")]
    public List<StepTiming>? Steps { get; set; }
}

